/* Throwaway functional demo. AI suggestions are deterministic rules, not model output. */
const MODULES = ['新品','联名','活动'];
function suggest(row) {
  const text = `${row.title} ${row.body || ''}`;
  const uncertain = /不确定|以门店为准|没有特别/.test(text);
  const rules = {新品:/新品|上新/,联名:/联名|IP/,活动:/买一赠一|套餐送|购买套餐送/};
  const declaredModules = String(row.modules || '').split(/[|｜]/).map(s => s.trim()).filter(m => MODULES.includes(m));
  const modules = declaredModules.length ? declaredModules : MODULES.filter(m => rules[m].test(text) && !(m==='新品' && /没有(?:特别的)?上新|并非新品|不是新品/.test(text)));
  const names = ['桂花乌龙','海獭日记','青提茉莉','买一赠一'];
  const name = names.find(n => text.includes(n));
  const action = String(row.action_name || '').trim() || name || row.title;
  return {...row, modules, action, peripherals: row.peripherals || (text.includes('玩偶') ? '玩偶' : ''),
    status:'pending', uncertain: uncertain || (!row.action_name && !name) || !modules.length,
    evidence: modules.map(m => `${m}：${text.match(rules[m])?.[0] ? `标题或正文命中“${text.match(rules[m])[0]}”` : '导入字段标注，需要人工核对。'}`).join('；') || '未找到明确市场动作，需要人工判断。', reason:'', history:[]};
}
function makeExportRows(notes) {
  const ids = new Map();
  return notes.filter(n => n.status==='approved').map(n => {
    const key=JSON.stringify([n.brand,n.action]); if(!ids.has(key)) ids.set(key,`ACTION-${String(ids.size+1).padStart(3,'0')}`);
    return {note_id:n.note_id,action_id:ids.get(key),brand:n.brand,action_name:n.action,title:n.title,published_date:n.published_date,likes:n.likes,likes_captured_at:n.likes_captured_at,modules:n.modules.join('|'),peripherals:n.peripherals,source_account:n.source_account,source_type:n.source_type,url:n.url||'',week_id:n.week_id||'',week_label:n.week_label||''};
  });
}
