function statusTag(n){return !n.locked&&n.status!=='pending'?badge('未确认','amber'):n.status==='approved'?badge('已确认','green'):n.status==='excluded'?badge('已排除','gray'):badge(state.suggested?'待复核':'待分析','amber');}
